module.exports = /*#__PURE__*/JSON.parse('{"Navigation":{"home":"Inicio","impressum":"Aviso Legal","privacy":"Política de Privacidad","contact":"Contacto","language":"Idioma","terms":"Términos de Uso"},"Meta":{"title":"App de Seguimiento de Fauna Silvestre & Exploración Natural | Wildscope","description":"Descubre la vida silvestre, explora la naturaleza y rastrea animales con la aplicación de acompañamiento al aire libre Wildscope impulsada por IA. Funciona sin conexión para aventuras en la naturaleza en cualquier lugar."},"Hero":{"title":"Tu Guía de Fauna Silvestre & Compañero Natural Impulsado por IA","subtitle":"¡No te pierdas nunca más un encuentro con la vida silvestre! Identifica plantas al instante, rastrea animales como un profesional y explora la naturaleza con confianza - incluso sin conexión a internet.","feature_1":"Reconocimiento y Seguimiento de Especies por IA","feature_2":"Mapas Sin Conexión y Base de Datos de Fauna","feature_3":"Cuestionarios Interactivos de Naturaleza y Aprendizaje","feature_4":"Navegación GPS y Herramientas de Brújula","feature_5":"Modo de Aventura Basado en Texto","feature_6":"Comunidad Global de Fauna Silvestre","appstore":"Descargar en App Store","playstore":"Obtener en Google Play","download_subtext":"Únete a miles de Entusiastas de la Naturaleza","cta":"Inicia Tu Aventura Salvaje Ahora","cta_subtext":"Únete a Miles de Entusiastas de la Naturaleza - Descarga Gratuita"},"About":{"title":"Transforma Tu Experiencia Natural con Seguimiento de Fauna por IA","paragraph1":"¡No dejes escapar momentos increíbles con la vida silvestre! Ya sea que estés caminando por senderos montañosos, explorando parques locales o descubriendo la fauna desde casa, nuestra avanzada tecnología de IA te ayuda a identificar plantas, rastrear animales y aprender sobre ecosistemas con precisión de experto.","image_alt":"Grupo diverso de personas usando la aplicación Wildscope en la naturaleza","bullet1":"Identifica plantas, animales y hongos al instante con tu cámara.","bullet2":"Accede a mapas detallados sin conexión y guías de supervivencia para cualquier aventura.","bullet3":"Conéctate con una comunidad global de entusiastas de la naturaleza y comparte descubrimientos.","paragraph2":"Desde paseos casuales por la naturaleza hasta expediciones a zonas silvestres remotas, Wildscope hace que cada aventura al aire libre sea inolvidable - con potente tecnología de identificación por IA, herramientas completas de exploración sin conexión y una comunidad global de apasionados por la naturaleza."},"Features":{"title":"Herramientas Completas de Identificación de Fauna y Exploración Natural","feature1_title":"Reconocimiento Avanzado de Fauna Silvestre","feature1_desc":"Identifica instantáneamente miles de especies con nuestro sistema de reconocimiento con IA. Obtén información detallada sobre animales, plantas y hongos, incluyendo patrones de comportamiento, preferencias de hábitat y variaciones estacionales.","feature1_point1":"Identificación de especies en tiempo real con IA","feature1_point2":"Base de datos completa de fauna silvestre","feature1_point3":"Patrones de seguimiento estacional","feature2_title":"Mapas Sin Conexión y Navegación","feature2_desc":"Nunca te pierdas con nuestro sistema completo de mapas sin conexión. Descarga mapas regionales y datos de fauna silvestre para navegación confiable e identificación de especies, incluso en áreas remotas sin servicio celular.","feature2_point1":"Descarga mapas para uso sin conexión","feature2_point2":"Seguimiento GPS y puntos de referencia","feature2_point3":"Herramientas de análisis de terreno","feature3_title":"Aprendizaje Interactivo","feature3_desc":"Aprende sobre la naturaleza a través de cuestionarios atractivos, desafíos y nuestro modo único de aventura basado en texto. Pon a prueba tus conocimientos, mejora tus habilidades al aire libre y descubre nuevas especies en tu área.","feature3_point1":"Cuestionarios de naturaleza personalizables","feature3_point2":"Escenarios de aventura basados en texto","feature3_point3":"Desafíos específicos de especies","feature4_title":"Acceso Completo Sin Conexión","feature4_desc":"Accede a todas las funciones esenciales sin conexión a internet. Nuestro modo sin conexión incluye datos de especies, mapas detallados, guías de fauna silvestre y herramientas de navegación - perfecto para aventuras remotas.","feature4_point1":"Funcionalidad completa sin conexión","feature4_point2":"Datos regionales descargables","feature4_point3":"Guías de especies sin conexión","feature5_title":"Guía Natural con IA","feature5_desc":"Obtén orientación personalizada de nuestro experto en naturaleza con IA. Haz preguntas sobre fauna silvestre local, recibe consejos específicos de especies y aprende sobre ecosistemas a través de conversación natural.","feature5_point1":"Asistente de naturaleza IA 24/7","feature5_point2":"Información contextual de fauna silvestre","feature5_point3":"Rutas de aprendizaje personalizadas","feature6_title":"Comunidad Global de Fauna Silvestre","feature6_desc":"Conéctate con entusiastas de la naturaleza en todo el mundo. Comparte avistamientos de fauna silvestre, descubre nuevas ubicaciones y contribuye a nuestra base de datos creciente de observaciones de especies.","feature6_point1":"Comparte encuentros con fauna silvestre","feature6_point2":"Descubre puntos destacados","feature6_point3":"Desafíos comunitarios"},"CallToAction":{"title":"¡No te Pierdas Ningún Momento Increíble con la Fauna Silvestre!","subtitle":"Únete a miles de entusiastas de la naturaleza que ya están descubriendo e identificando la vida silvestre como nunca antes. ¡Descarga Wildscope ahora y transforma tus aventuras al aire libre!","appstore":"Descargar en App Store","playstore":"Obtener en Google Play","button":"Inicia Tu Viaje Salvaje","playstoreLink":"https://play.google.com/store/apps/details?id=com.duselk.theoutdoorbible","benefits":["✓ Identificación Instantánea de Plantas & Animales","✓ Funciona Sin Conexión en Áreas Remotas","✓ Navegación & Seguimiento GPS","✓ Guía Natural Impulsado por IA","✓ Comunidad Global de Fauna Silvestre"]},"Footer":{"copyright":"© {year} Wildscope. Todos los derechos reservados.","impressum":"Aviso Legal","privacy":"Política de privacidad","contact":"Contacto"},"CookieBanner":{"message":"Este sitio web utiliza cookies para asegurar que obtengas la mejor experiencia en nuestro sitio.","accept":"Aceptar","decline":"Rechazar"},"ImpressumPage":{"title":"Aviso Legal","section1_title":"Información según § 5 TMG (ley alemana)","address":"Dustin Keßler<br />Kurt Schumacher Straße 93<br />46539 Dinslaken<br />Alemania","contact_title":"Contacto","contact_email":"Correo electrónico: ","responsibility_title":"Responsable del contenido según § 55 párrafo 2 RStV (ley alemana)","disclaimer_title":"Exención de responsabilidad","disclaimer_text":"El contenido de nuestro sitio ha sido creado con el máximo cuidado. Sin embargo, no podemos garantizar la exactitud, integridad y actualidad del contenido. Como proveedor de servicios, somos responsables de nuestro propio contenido en estas páginas de acuerdo con las leyes generales según el § 7 párrafo 1 TMG (ley alemana). Según los §§ 8 a 10 TMG (ley alemana), como proveedor de servicios, no estamos obligados a monitorear la información transmitida o almacenada por terceros, ni a investigar circunstancias que indiquen una actividad ilegal."},"PrivacyPage":{"content":"# Política de privacidad de Wildscope\\n\\n**Última actualización:** 06 de febrero de 2025\\n\\n## 2. ¿Qué datos recopilamos?\\nLa mayoría de los datos se almacenan localmente en tu dispositivo. Los datos solo se almacenan en la nube o en servicios externos cuando utilizas funciones específicas.\\n\\n### 📍 Datos de ubicación y actividad\\n• La mayor parte del procesamiento de la ubicación ocurre localmente en tu dispositivo.\\n• Almacenamos los países, biomas, reinos y ecorregiones visitados en tu perfil de usuario (sin datos de GPS o de ubicación exacta).\\n• Los datos de ubicación solo se envían a servicios externos cuando se utilizan ciertas funciones:\\n  - APIs de Google Maps, Places y Geocoding: Mapas, autocompletado y búsqueda de PDI (Puntos de Interés).\\n  - Mapbox: Estilos de mapa, teselas y navegación (usuarios Premium).\\n  - OpenStreetMap (OSM): Búsqueda de PDI y datos de mapa.\\n  - GBIF: Consulta de animales y plantas en tu región.\\n  - OpenWeather y RainViewer: Datos meteorológicos y de radar.\\n  - Open Elevation y OpenTopo: Análisis del terreno.\\n  - Google Gemini y OpenAI: Funciones de IA (p. ej., cuestionario, modo aventura).\\n\\n### 💾 Firebase para almacenamiento y autenticación\\n\\n• Utilizamos Firebase (región de Fráncfort) para la autenticación de usuarios y el almacenamiento de datos.\\n\\n• Datos como cuentas de usuario, publicaciones, comentarios, subidas y regiones visitadas se almacenan en Firebase.\\n\\n• Firebase implementa sus propios controles de seguridad y acceso para proteger tus datos.\\n\\n• Puedes solicitar la eliminación completa de tu cuenta y los datos asociados en cualquier momento.\\n\\n### 📊 Análisis de PostHog y uso de la aplicación\\n\\n• Utilizamos PostHog para obtener estadísticas de uso anonimizadas.\\n\\n• PostHog nos ayuda a entender y mejorar el uso de la aplicación.\\n\\n• Los datos recopilados incluyen: pantallas visitadas, interacciones con la aplicación, duración de la sesión.\\n\\n• No se vinculan datos personales a tu cuenta.\\n\\n• Puedes desactivar el seguimiento en cualquier momento en los ajustes.\\n\\n### 👤 Datos de la cuenta de usuario y del perfil\\n\\n• Se requiere registro.\\n\\n• Almacenamiento de: nombre de usuario, dirección de correo electrónico, estado premium.\\n\\n• Las contraseñas se almacenan cifradas.\\n\\n### 📤 Subidas e interacciones\\nLos datos solo se almacenan en la nube cuando:\\n\\n• Compartes una imagen o un vídeo: Nombre de usuario, fecha y lugar de captura.\\n\\n• Creas una publicación: Se almacena el texto, pero no tu ubicación.\\n\\n• Das \\"me gusta\\" o comentas: Solo se almacena la interacción en sí.\\n\\n### 🎥 Servicios y API de terceros\\n\\n• Mapas y ubicación: Google Maps, Places, APIs de Geocoding y Mapbox (usuarios Premium).\\n\\n• Datos de naturaleza: GBIF para información de especies, PlantNet para identificación de plantas.\\n\\n• Clima: OpenWeather y RainViewer para datos meteorológicos.\\n\\n• Terreno: Open Elevation y OpenTopo para datos de elevación.\\n\\n• Contenido: Vídeos de YouTube, artículos e imágenes de Wikipedia/Wikimedia.\\n\\n• Servicios de IA: Google Gemini y OpenAI para funciones interactivas.\\n\\n• Cada servicio procesa los datos de acuerdo con sus propias políticas de privacidad.\\n\\n• Las funciones Premium utilizan RevenueCat para el procesamiento de pagos.\\n\\n### 📺 Uso de los servicios de la API de YouTube\\nNuestra aplicación utiliza los Servicios de la API de YouTube para proporcionarte contenido de vídeo relacionado con actividades al aire libre, naturaleza y habilidades de supervivencia. Al utilizar nuestra función de Media Feed, reconoces y aceptas estar sujeto a los Términos de servicio de YouTube (https://www.youtube.com/t/terms) y a la Política de privacidad de Google (http://www.google.com/policies/privacy).\\n\\n#### Recopilación y acceso a datos\\nCuando utilizas nuestra función de Media Feed, accedemos y recopilamos la siguiente información a través de los Servicios de la API de YouTube:\\n\\n**De la API de YouTube:**\\n\\n• Metadatos públicos de vídeos, incluyendo títulos, descripciones, miniaturas, nombres de canales y fechas de publicación.\\n• URLs e identificadores de vídeos.\\n• Resultados de búsqueda basados en tu ubicación y categorías de contenido seleccionadas.\\n\\n**De tu dispositivo:**\\n\\n• Tus datos de ubicación (cuando los feeds basados en la ubicación están habilitados) para proporcionar contenido de vídeo geográficamente relevante.\\n• Preferencias y ajustes de la aplicación almacenados localmente en tu dispositivo.\\n• Datos de vídeo almacenados temporalmente en la caché del almacenamiento local de tu dispositivo.\\n\\n#### Almacenamiento y caché de datos\\n\\n• Los metadatos de vídeo obtenidos de la API de YouTube se almacenan en la caché local de tu dispositivo por hasta 24 horas para mejorar el rendimiento de la aplicación y reducir el uso de datos.\\n\\n• Los datos en caché incluyen detalles del vídeo, marcas de tiempo, categorías seleccionadas, alcance de la ubicación e información de la ubicación.\\n\\n• No se almacenan datos de autenticación del usuario ni información personal de la cuenta de YouTube.\\n\\n• Todos los datos en caché se almacenan localmente en tu dispositivo utilizando AsyncStorage y no se transmiten a servidores externos.\\n\\n#### Uso y procesamiento de datos\\nUtilizamos la información recopilada para:\\n\\n• Mostrar contenido de vídeo relevante sobre actividades al aire libre y naturaleza en nuestro Media Feed.\\n\\n• Proporcionar recomendaciones de vídeo basadas en la ubicación cuando habilitas los feeds de ubicación.\\n\\n• Almacenar contenido en caché localmente para mejorar el rendimiento de la aplicación y la capacidad sin conexión.\\n\\n• Filtrar y ordenar los resultados de vídeo según tus preferencias y ubicación.\\n\\n#### Intercambio de datos y terceros\\n\\n• No compartimos ningún dato de usuario o de la API de YouTube con terceros con fines comerciales.\\n\\n• Las interacciones de vídeo dentro de los reproductores de YouTube insertados están sujetas a las propias prácticas de privacidad de YouTube y pueden ser rastreadas por Google/YouTube.\\n\\n• Nuestra aplicación utiliza sus propias credenciales de la API de YouTube y no accede a tu cuenta personal de YouTube.\\n\\n• Los datos de ubicación utilizados para las búsquedas de vídeo se procesan localmente y se combinan con términos de búsqueda públicos.\\n\\n#### Cookies e información del dispositivo\\n\\n• Al ver vídeos de YouTube insertados, YouTube puede colocar cookies o tecnologías similares en tu dispositivo de acuerdo con las prácticas de privacidad de Google.\\n\\n• Nuestra aplicación accede al almacenamiento local del dispositivo (AsyncStorage) para almacenar en caché contenido de vídeo y guardar las preferencias del usuario.\\n\\n• Podemos recopilar información del dispositivo necesaria para la funcionalidad de la aplicación, incluidos los datos de ubicación para funciones basadas en la localización.\\n\\n#### Retención de datos\\n\\n• Los metadatos de vídeo almacenados localmente en la caché se eliminan automáticamente después de 24 horas.\\n\\n• Las preferencias y ajustes del usuario permanecen almacenados localmente hasta que desinstales la aplicación o borres manualmente los datos de la aplicación.\\n\\n• Ningún dato de la API de YouTube se almacena permanentemente en servidores externos.\\n\\n#### Derechos y control del usuario\\nPuedes:\\n\\n• Desactivar los feeds de vídeo basados en la ubicación en los ajustes de la aplicación.\\n• Borrar los datos en caché actualizando el Media Feed o borrando el almacenamiento de la aplicación.\\n• Acceder a los vídeos de YouTube directamente a través de la aplicación o el sitio web de YouTube, donde se aplican los controles de privacidad de Google.\\n• Contactarnos para solicitar información sobre los datos recopilados a través de nuestra aplicación.\\n\\n#### Políticas de privacidad de terceros\\nAl utilizar los Servicios de la API de YouTube dentro de nuestra aplicación, también estás sujeto a:\\n\\n• Política de privacidad de Google: http://www.google.com/policies/privacy\\n• Términos de servicio de YouTube: https://www.youtube.com/t/terms\\n\\n### 🤖 Consentimiento de IA\\nCiertas funciones de esta aplicación utilizan servicios de IA proporcionados por OpenAI y/o Google Gemini. Estos servicios pueden procesar datos de usuario fuera de la UE. Ninguna función de IA está habilitada por defecto. Al activar explícitamente las funciones de IA en la aplicación, proporcionas tu consentimiento según el Art. 6(1)(a) del RGPD. Puedes retirar este consentimiento en cualquier momento a través de los ajustes de la aplicación.\\n\\n## 3. ¿Por qué procesamos tus datos?\\nBases legales según el RGPD:\\n\\n• Art. 6(1)(a) (Consentimiento): Compartir ubicación, uso de IA, subidas.\\n\\n• Art. 6(1)(b) (Cumplimiento de contrato): Cuenta de usuario y membresía premium.\\n\\n• Art. 6(1)(f) (Interés legítimo): Mejora de la aplicación a través de los análisis de PostHog.\\n\\n## 4. Almacenamiento y eliminación de datos\\n¿Dónde se almacenan tus datos?\\n\\n• Datos de ubicación: Localmente, no se almacenan permanentemente.\\n\\n• Publicaciones, \\"me gusta\\", subidas: En Firebase (región de Fráncfort), si se comparten activamente.\\n\\n• Datos de análisis: Anonimizados a través de PostHog.\\n\\n• La mayoría de los datos de la aplicación se almacenan localmente en tu dispositivo.\\n\\n• Servidores backend: Ubicados en EE. UU. y Europa (Heroku).\\n\\n• Identificación de plantas: API de PlantNet (servicio externo).\\n\\n• Feed de noticias: API de Google News.\\n\\n• Procesamiento de pagos: RevenueCat (sin almacenamiento directo de datos de pago).\\n\\nEliminación de datos:\\n\\n• Todos los datos se pueden eliminar en los ajustes de la aplicación.\\n\\n• La eliminación de la cuenta elimina todos los datos vinculados en Firebase.\\n\\n## 5. ¿Quién tiene acceso a tus datos?\\n\\n• No se comparten con fines publicitarios.\\n\\n• Los datos de ubicación solo se envían temporalmente a servicios externos.\\n\\n• YouTube y Wikimedia recopilan sus propios datos cuando se utilizan.\\n\\n• PostHog procesa estadísticas de uso anónimas.\\n\\n• Se utilizan las APIs de Google para diversas funciones.\\n\\n• No se almacenan datos de pago (Google Play / Apple Pay).\\n\\n## 6. Tus derechos bajo el RGPD\\n\\n• Información sobre los datos almacenados.\\n\\n• Corrección de datos incorrectos.\\n\\n• Eliminación de tus datos.\\n\\n• Portabilidad de datos.\\n\\n• Retirada del consentimiento en cualquier momento.\\n\\n📧 Contacto para preguntas de privacidad: duselkay@gmail.com\\n\\n## 1. Responsable del tratamiento\\nDustin Keßler\\nDirección: Kurt Schumacher Straße 93, 46539 Dinslaken\\nEmail: duselkay@gmail.com"},"TermsPage":{"title":"Términos de Uso","content":"# Términos de Uso\\n\\nÚltima actualización: 6 febrero 2025\\n\\n## 1. General\\nEstos Términos de Uso regulan el uso de la app Wildscope. Al crear una cuenta, aceptas estos términos. La edad mínima para usarla es de 16 años. La aplicación ofrece funciones para observación de fauna, identificación de plantas y exploración de la naturaleza, pensadas para mejorar tu experiencia al aire libre.\\n\\n## 2. Funciones de la app\\nWildscope proporciona datos geolocalizados sobre animales, plantas, puntos de interés e información meteorológica. La app incluye funciones basadas en IA (quizzes de naturaleza, modo aventura), permite subir fotos y vídeos, crear publicaciones y acceder a funciones premium con contenido y funcionalidades avanzadas.\\n\\n## 3. Cuenta de usuario y responsabilidades\\nEres responsable de la seguridad de tu cuenta y de usar una contraseña segura. Los usuarios deben cumplir con todas las leyes y regulaciones aplicables.\\n\\n### Contenido prohibido\\nEstá prohibido publicar contenido ilegal, ofensivo o protegido por derechos de autor. La manipulación de datos de ubicación está estrictamente prohibida. Puedes eliminar tu cuenta en cualquier momento desde la configuración de la app.\\n\\n## 4. Gestión técnica de datos\\nLa mayoría de los datos se almacenan localmente en tu dispositivo para optimizar el rendimiento y la privacidad. Firebase se utiliza para autenticación y almacenamiento en la nube cuando es necesario. PostHog recopila estadísticas anonimadas para mejorar la app. Se usan APIs de Google para diversas funciones. No utilizamos tus datos con fines publicitarios.\\n\\n## 5. Membresía premium\\nLas funciones premium están disponibles a través de Google Play o Apple Pay. No hay derecho de desistimiento tras el uso de funciones premium. Las suscripciones premium se pueden cancelar en cualquier momento desde su respectiva tienda.\\n\\n## 6. Descargo de responsabilidad\\n### Limitación de responsabilidad\\nNo nos hacemos responsables de:\\n• Información incorrecta o desactualizada sobre plantas, animales o puntos de interés\\n• Daños derivados del uso incorrecto de consejos de supervivencia o información natural\\n• Pérdida de datos, fallos en la app o indisponibilidad temporal de funciones\\n• Vulnerabilidades de seguridad causadas por servicios de terceros\\n• Contenido generado por IA y las decisiones basadas en él: todas las salidas de IA (texto, imagen, audio, sugerencias) se proporcionan sin garantía de exactitud, seguridad o aptitud. Su uso es bajo tu propia responsabilidad, especialmente en situaciones de emergencia o supervivencia.\\n\\n### Contenido IA e uso en emergencias\\nWildscope incluye funciones experimentales basadas en IA, proporcionadas por terceros como OpenAI y Google Gemini. Estos pueden generar contenido inexacto, engañoso o inapropiado. No confíes en contenido generado por IA en situaciones críticas. Las decisiones basadas en él son exclusiva responsabilidad del usuario. Nos eximimos de toda responsabilidad por daños derivados de tales decisiones.\\n\\n## 7. Derechos sobre contenido\\n### Contenido generado por el usuario\\nTodo contenido que subas o generes te pertenece. Por defecto es privado, salvo que decidas compartirlo. Eliminaremos contenido ilegal sin previo aviso.\\n\\n### Contenido de la app y derechos de autor\\nTodos los contenidos de la app, incluidos datos, textos y gráficos, están protegidos por derechos de autor. No puedes utilizarlos comercialmente sin permiso por escrito.\\n\\n## 8. Integración con YouTube\\nNuestra app integra los servicios de la API de YouTube para ofrecer contenido de vídeo. El uso de cualquier función relacionada con YouTube está sujeto a los [Términos de Servicio de YouTube](https://www.youtube.com/t/terms), integrados en estos Términos.\\n\\n### Uso permitido\\nAl usar el Media Feed, te comprometes a:\\n• Cumplir con los Términos de Servicio y las Directrices de la comunidad de YouTube\\n• Usar los vídeos sólo con fines personales, sin fines comerciales\\n• No descargar, extraer ni redistribuir contenido fuera de lo previsto por la app\\n• Respetar los derechos de propiedad intelectual de YouTube y los creadores de contenido\\n\\n### Exención de responsabilidad por YouTube\\n• No nos responsabilizamos de la exactitud, legalidad o idoneidad del contenido de YouTube mostrado\\n• El contenido es proporcionado por terceros y no refleja necesariamente nuestra opinión\\n• La disponibilidad o funcionalidad de los vídeos puede cambiar sin previo aviso por cambios en políticas o sistemas de YouTube\\n\\n### Tratamiento de datos por YouTube\\nAl usar funciones relacionadas con YouTube, confirmas que:\\n• Google/YouTube pueden procesar tus datos de interacción según sus políticas de privacidad\\n• Los reproductores integrados pueden recopilar datos de uso directamente\\n• Actuamos como procesadores de datos de la API de YouTube, sin poder controlar las prácticas de YouTube\\n\\n## 9. Reembolsos\\nTodos los pagos se gestionan a través de Google Play Store o Apple App Store. Se aplican las políticas de reembolso respectivas.\\n\\nNo ofrecemos reembolsos en casos de:\\n• Funciones de IA o multimedia no disponibles por agotamiento de cuotas\\n• Problemas temporales por fallos en APIs de terceros\\n• Incompatibilidad con tu dispositivo o falta de conectividad\\n\\nEres responsable de cancelar tu suscripción antes de su renovación. No tenemos acceso a los sistemas de facturación de las plataformas.\\n\\n## 10. Servicios externos y límites de API\\nWildscope depende de servicios externos y APIs, sujetos a límites de uso, interrupciones y restricciones, tanto para usuarios gratuitos como premium.\\n\\n**Servicios utilizados (algunos ejemplos):**\\n• APIs de Google (Maps, Places, Geocoding, Static Maps)\\n• Mapbox (tiles, estilos, navegación)\\n• PlantNet (reconocimiento de plantas)\\n• YouTube Data API\\n• APIs de Wikipedia / Wikimedia\\n• OpenStreetMap / Overpass\\n• GBIF (biodiversidad)\\n• RainViewer y OpenWeatherMap (meteorología y radar)\\n• Open Elevation y OpenTopo\\n• RevenueCat (gestion de pagos in‑app)\\n• Firebase (autenticación, almacenamiento, Firestore)\\n• OpenAI y Google Gemini (servicios IA)\\n\\nNo nos responsabilizamos de interrupciones, degradación o limitaciones causadas por estos servicios. Ejemplos:\\n• PlantNet permite un máximo de 500 solicitudes/día en plan gratuito\\n• Mapbox puede dejar de servir tiles tras superar cuota mensual\\n• OpenAI/Gemini pueden suspender el acceso si superas cuotas o costes\\n\\n## 11. Avisos legales\\n• No garantizamos la exactitud, integridad o fiabilidad de la información, recomendaciones ni consejos proporcionados\\n• Todas las funciones, incluidas IA, mapas o herramientas de reconocimiento, tienen fines informativos o de entretenimiento\\n• Wildscope no es una herramienta certificada para emergencias, uso médico o supervivencia\\n• Eres responsable de cumplir con las leyes locales al usar funciones de especies, geolocalización o publicación de contenido\\n\\n## 12. Cambios en los Términos de Uso\\nSi sigues usando la app después de actualizaciones, se considerará que aceptas los nuevos términos. Te informaremos sobre cambios importantes mediante notificación en la app o correo electrónico.\\n\\n## 13. Contacto\\nPara soporte o preguntas sobre estos términos, contáctanos en: duselkay@gmail.com"},"ContactPage":{"title":"Contacto","contact_intro":"No dudes en contactarnos para cualquier pregunta, comentario o consulta.","contact_person":"Persona de contacto","country":"Alemania"},"NotFound":{"title":"Página No Encontrada","description":"Lo sentimos, la página que estás buscando no existe o ha sido movida.","backHome":"Volver a la Página Principal"},"General":{"loading":"Cargando...","comingSoon":"Próximamente"},"FAQ":{"title":"Preguntas Frecuentes sobre el Seguimiento de Fauna Silvestre","question1":"¿Cómo se compara Wildscope con otras aplicaciones de identificación natural como iNaturalist?","answer1":"Mientras que iNaturalist se centra principalmente en la identificación de especies y la ciencia ciudadana, Wildscope ofrece una experiencia al aire libre completa con características adicionales diseñadas específicamente para entusiastas de la naturaleza. Nuestra aplicación incluye identificación de fauna silvestre sin conexión, herramientas de navegación GPS para exploración en áreas silvestres, aprendizaje interactivo a través de cuestionarios sobre naturaleza y un compañero de IA que comprende tu entorno para proporcionar orientación personalizada—haciéndola perfecta tanto para amantes casuales de la naturaleza como para rastreadores serios de fauna silvestre.","question2":"¿Puedo identificar plantas y animales sin conexión con Wildscope?","answer2":"Parcialmente. El análisis de IA requiere una conexión a Internet, pero verás todas las especies rastreadas de tu área mostradas y puedes usar estas para ayudar con la identificación.","question3":"¿Qué dispositivos admiten la aplicación de exploración natural Wildscope?","answer3":"Las funciones de seguimiento de fauna silvestre e identificación natural de Wildscope están disponibles tanto para dispositivos iOS (iPhone/iPad) como Android a través de App Store y Google Play Store, haciéndola accesible prácticamente para todos los usuarios de smartphones.","question4":"¿Es gratuita la aplicación de identificación de fauna silvestre Wildscope?","answer4":"Wildscope ofrece una versión gratuita con funciones esenciales de identificación de fauna silvestre y exploración natural. Nuestra suscripción premium desbloquea capacidades avanzadas como hallazgos ilimitados de especies, más créditos, más lugares personalizados para visitar y beneficios adicionales. Consulta la aplicación para ver las opciones de suscripción actuales.","question5":"¿Qué tan precisa es la identificación de plantas y animales de Wildscope?","answer5":"Wildscope combina datos de ubicación con tecnología avanzada de IA para identificar fauna silvestre y plantas con alta precisión. Mientras nuestro sistema de reconocimiento mejora continuamente, la precisión de identificación varía según la especie, la calidad de la imagen y el ángulo de visión. Estamos mejorando constantemente nuestros algoritmos mediante actualizaciones regulares para proporcionar una identificación cada vez más precisa de fauna silvestre y plantas en todos los entornos.","question6":"¿Puedo contribuir a la base de datos de fauna silvestre de Wildscope?","answer6":"¡Absolutamente! Wildscope prospera gracias a las contribuciones de la comunidad. Tus observaciones de fauna silvestre e identificaciones de plantas se agregan de forma segura a nuestra base de datos del ecosistema, mejorando la precisión de la aplicación para todos. Este enfoque colaborativo crea un recurso completo de identificación de fauna silvestre que beneficia a todos los entusiastas de la naturaleza.","question7":"¿Wildscope está desarrollado por una gran empresa tecnológica?","answer7":"No, Wildscope es un proyecto independiente desarrollado por un entusiasta de la naturaleza dedicado. La aplicación está diseñada y mantenida por un solo desarrollador apasionado que prioriza la precisión y la experiencia del usuario sobre la monetización. Este enfoque independiente asegura que Wildscope permanezca fiel a su misión principal: ayudar a las personas a conectarse con y entender la naturaleza sin comprometer la privacidad o la experiencia del usuario."},"OfflineCapabilities":{"title":"Capacidades Sin Conexión – Explora Sin Límites","intro":"Una vez que hayas cargado un área, puedes disfrutar de exploración completa incluso sin acceso a internet:","capability1":"Mapas y Senderos Sin Conexión","capability2":"Datos de Especies Locales y Puntos de Referencia Naturales","capability3":"PDI y Destacados Añadidos por la Comunidad","libraries_title":"Bibliotecas de Conocimiento:","library1":"Plantas Comestibles","library2":"Técnicas de Navegación","library3":"Primeros Auxilios Básicos","library4":"Construcción de Refugios","library5":"Guías de Fuego y Agua","library6":"Brújula, Herramienta Morse y más","library7":"Cuestionarios Básicos de Naturaleza"},"OnlineFeatures":{"title":"Funciones En Línea – Mejoradas por IA","intro":"Mantente conectado para la experiencia completa:","feature1_title":"Entrenador Wildscope","feature1_desc":"Pregunta sobre tu entorno, sube imágenes y obtén orientación personalizada.","feature2_title":"Identificación Potenciada por IA","feature2_desc":"Reconoce especies instantáneamente usando fotos y accede a información profunda y consciente de la ubicación.","feature3_title":"Perspectivas Inteligentes","feature3_desc":"Aprende historia local, hallazgos comunitarios, patrones estacionales y más.","feature4_title":"Comunidad Global y Compartir","feature4_desc":"Comparte tus descubrimientos, rastrea avistamientos raros y explora rutas curadas por usuarios.","feature5_title":"Cuestionarios Basados en Ubicación y Aventuras de Texto","feature5_desc":"Interactúa con tu entorno a través de experiencias ricas e inmersivas."},"Audience":{"title":"¿Para Quién es Wildscope?","intro":"Tanto si eres un explorador experimentado como si acabas de empezar tu viaje por la naturaleza, Wildscope está diseñado para ti:","audience1_title":"Senderistas & Excursionistas","audience1_desc":"Navega por senderos, identifica especies y mantente seguro con mapas offline y herramientas de supervivencia.","audience2_title":"Fotógrafos de Naturaleza & Observadores de Aves","audience2_desc":"Descubre, rastrea e identifica especies esquivas para capturar esa foto perfecta.","audience3_title":"Familias & Exploradores Casuales","audience3_desc":"Convierte las visitas al parque en emocionantes aventuras de aprendizaje para todas las edades.","audience4_title":"Educadores & Estudiantes","audience4_desc":"Una potente herramienta para la educación al aire libre, proyectos de biodiversidad y estudios de la naturaleza.","audience5_title":"Supervivencialistas & Aficionados al Bushcraft","audience5_desc":"Perfecciona tus habilidades con identificación de plantas, guías para construir refugios y recursos offline.","conclusion":"¡Y cualquiera con curiosidad por el mundo natural!"},"Testimonials":{"title":"Lo que Dicen Nuestros Exploradores","testimonial1":"Wildscope ha cambiado por completo mi forma de explorar. ¡Los mapas sin conexión son un salvavidas y la identificación con IA es increíblemente precisa!","testimonial1_author":"Sarah L.","testimonial1_role":"Entusiasta del Senderismo","testimonial2":"Como profesor de biología, esta aplicación es una herramienta fantástica para mis alumnos. Hace que aprender sobre la flora y fauna local sea mucho más interactivo.","testimonial2_author":"David K.","testimonial2_role":"Educador"},"Pricing":{"title":"Elige Tu Plan Wildscope","free_title":"Explorador Básico","free_subtitle":"Comienza tu viaje con funciones esenciales.","free_price":"Gratis","free_price_suffix":"Para siempre","free_feature1":"Identificación de especies IA (limitada)","free_feature2":"Mapas regionales offline (1 región)","free_feature3":"Acceso a guía básica de supervivencia","free_feature4":"Acceso al foro de la comunidad","free_feature5":"Rastrear 5 PDI favoritos","free_feature_limited1":"Experiencia con anuncios","free_cta":"Incluido con la descarga","pro_badge":"Mejor Valor","pro_title":"Wildscope Pro","pro_subtitle":"Desbloquea todo el poder de la exploración de la naturaleza.","pro_price":"2,99 €","pro_price_suffix":"al mes (o 17,99 €/año)","pro_feature1":"Identificación de especies IA ilimitada","pro_feature2":"Mapas regionales offline ilimitados","pro_feature3":"Guía de supervivencia completa y herramientas avanzadas","pro_feature4":"Funciones comunitarias Premium","pro_feature5":"Rastrear PDI favoritos ilimitados","pro_feature6":"Experiencia sin anuncios","pro_feature7":"Soporte prioritario","pro_cta":"Hazte Pro y Explora Más","footnote":"Los precios pueden variar según la región. Las suscripciones se gestionan a través de App Store/Google Play."}}');

